Widget _assetIcon(String path, {double size = 20, Color? color}) {
  return Image.asset(
    path,
    width: size,
    height: size,
    fit: BoxFit.contain,
    color: color,
    colorBlendMode: color == null ? null : BlendMode.srcIn,
    errorBuilder: (_, __, ___) =>
        AppIcon(Icons.image_not_supported, size: size),
  );
}

String _homeBackgroundForAffinity(String affinityCode, {required bool isDark}) {
  switch (affinityCode.trim().toLowerCase()) {
    case 'sprout':
    case 'mam_non':
      return isDark ? AppAssets.homeSproutDark : AppAssets.homeSprout;
    case 'dawn':
    case 'binh_minh':
      return isDark ? AppAssets.homeDawnDark : AppAssets.homeDawn;
    case 'warm_sun':
    case 'nang_am':
      return isDark ? AppAssets.homeWarmSunDark : AppAssets.homeWarmSun;
    case 'moonlight':
    case 'anh_trang':
      return isDark ? AppAssets.homeMoonlight : AppAssets.homeMoonlightLight;
    default:
      return isDark ? AppAssets.homeSproutDark : AppAssets.homeSprout;
  }
}

double _responsivePetScale(Size viewport) {
  final heightScale = (viewport.height / 720).clamp(0.58, 1.0);
  final widthScale = (viewport.width / 360).clamp(0.72, 1.0);
  return math.min(heightScale, widthScale).toDouble();
}

double _responsivePetVerticalOffset({
  required String affinityCode,
  required int stageNo,
  required Size viewport,
}) {
  final preferredOffset =
      affinityCode.trim().toLowerCase() == 'warm_sun' && stageNo == 1
      ? 176.0
      : 62.0;
  final availableHeightFactor = ((viewport.height - 400) / 480).clamp(0.0, 1.0);
  return preferredOffset * availableHeightFactor;
}

