class _StatBar extends StatelessWidget {
  const _StatBar({
    required this.label,
    required this.value,
    required this.maximum,
    required this.barColor,
  });

  final String label;
  final int value;
  final int maximum;
  final Color barColor;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final safeMaximum = maximum <= 0 ? 1 : maximum;
    final safeValue = value.clamp(0, safeMaximum);
    final progress = (safeValue / safeMaximum).clamp(0.0, 1.0);
    final mutedFg = isDark
        ? AppColors.darkMutedForeground
        : AppColors.lightMutedForeground;

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        SizedBox(
          // Keep the compact Home bars proportional to the full Spirit Detail
          // bars: 17px track, 29px leaf and centered value text.
          height: 30,
          child: Stack(
            alignment: Alignment.center,
            clipBehavior: Clip.none,
            children: [
              Positioned(
                left: 0,
                right: 14,
                child: Container(
                  height: 17,
                  clipBehavior: Clip.antiAlias,
                  decoration: BoxDecoration(
                    color: isDark ? AppColors.darkMuted : AppColors.creamLight,
                    borderRadius: BorderRadius.circular(999),
                    border: Border.all(
                      color: isDark ? AppColors.darkBorder : AppColors.woodDeep,
                      width: 1.5,
                    ),
                  ),
                  child: TweenAnimationBuilder<double>(
                    tween: Tween<double>(begin: 0, end: progress),
                    duration: const Duration(milliseconds: 700),
                    curve: Curves.easeOutCubic,
                    builder: (context, animatedValue, child) => Align(
                      alignment: Alignment.centerLeft,
                      child: FractionallySizedBox(
                        widthFactor: animatedValue.clamp(0.0, 1.0),
                        child: DecoratedBox(
                          decoration: BoxDecoration(
                            color: barColor,
                            borderRadius: BorderRadius.circular(999),
                          ),
                          child: const SizedBox.expand(),
                        ),
                      ),
                    ),
                  ),
                ),
              ),
              Positioned.fill(
                right: 14,
                child: Center(
                  child: Text(
                    '$safeValue/$safeMaximum',
                    style: TextStyle(
                      fontSize: 9,
                      fontWeight: FontWeight.w900,
                      color: isDark
                          ? AppColors.darkForeground
                          : AppColors.inkDark,
                      height: 1,
                    ),
                  ),
                ),
              ),
              const Positioned(
                right: -2,
                child: CustomPaint(
                  size: Size(29, 29),
                  painter: _HomeProgressLeafPainter(),
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 1),
        Text(
          label,
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: TextStyle(
            fontSize: 9,
            fontWeight: FontWeight.w800,
            color: mutedFg,
          ),
          textAlign: TextAlign.center,
        ),
      ],
    );
  }
}

class _HomeProgressLeafPainter extends CustomPainter {
  const _HomeProgressLeafPainter();

  @override
  void paint(Canvas canvas, Size size) {
    final leaf = Path()
      ..moveTo(size.width * 0.1, size.height * 0.78)
      ..cubicTo(
        size.width * 0.18,
        size.height * 0.18,
        size.width * 0.68,
        size.height * 0.02,
        size.width * 0.9,
        size.height * 0.1,
      )
      ..cubicTo(
        size.width,
        size.height * 0.5,
        size.width * 0.66,
        size.height * 0.92,
        size.width * 0.1,
        size.height * 0.78,
      )
      ..close();
    canvas.drawPath(leaf, Paint()..color = AppColors.leafBright);
    canvas.drawPath(
      leaf,
      Paint()
        ..color = AppColors.oliveDeep
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.1,
    );
    canvas.drawLine(
      Offset(size.width * 0.08, size.height * 0.88),
      Offset(size.width * 0.8, size.height * 0.18),
      Paint()
        ..color = AppColors.oliveDeep
        ..strokeWidth = 0.9,
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

