class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key, required this.title});
  final String title;

  @override
  State<HomeScreen> createState() => _HomeScreenState();
}

class _HomeScreenState extends State<HomeScreen> with TickerProviderStateMixin {
  String? _petAnimationOverride;
  bool _stepExpanded = false;
  bool _isRefreshingMetrics = false;
  bool _isFeedButtonPressed = false;
  int? _dewBalance;
  final WalletRepository _walletRepository = WalletRepository();
  final MissionsScreenRepository _missionsRepository =
      MissionsScreenRepository();
  final NotificationDatasource _notificationDatasource =
      NotificationDatasourceImpl(ApiClient());
  bool _showDailyLoginBadge = false;
  bool _showMissionBadge = false;
  bool _showNotificationBadge = false;
  Timer? _refreshTimer;
  Timer? _petAnimationTimer;
  final List<_FloatingNum> _floatingNums = [];
  final List<_FloatingBubble> _bubbles = [
    _FloatingBubble(id: 1, top: 0.20, left: 0.12, size: 30),
    _FloatingBubble(id: 2, top: 0.18, left: 0.72, size: 38),
    _FloatingBubble(id: 3, top: 0.55, left: 0.08, size: 26),
    _FloatingBubble(id: 4, top: 0.60, left: 0.78, size: 32),
  ];

  // Glow animation
  late final AnimationController _glowCtrl;
  late final Animation<double> _glowScale;
  late final Animation<double> _glowOpacity;

  // Feed ripple animation
  late final AnimationController _rippleCtrl;

  // Tap hint blink
  late final AnimationController _hintCtrl;

  @override
  void initState() {
    super.initState();

    // Glow pulse behind pet
    _glowCtrl = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 3),
    );
    _glowScale = Tween<double>(
      begin: 1.0,
      end: 1.1,
    ).animate(CurvedAnimation(parent: _glowCtrl, curve: Curves.easeInOut));
    _glowOpacity = Tween<double>(
      begin: 0.35,
      end: 0.65,
    ).animate(CurvedAnimation(parent: _glowCtrl, curve: Curves.easeInOut));

    // Feed ripple
    _rippleCtrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 550),
    );

    // Hint blink
    _hintCtrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2500),
    )..repeat(reverse: true);

    WidgetsBinding.instance.addPostFrameCallback((_) {
      unawaited(_refreshHomeMetrics());
    });

    _refreshTimer = Timer.periodic(const Duration(minutes: 1), (_) {
      unawaited(_refreshHomeMetrics());
    });
  }

  void _playLevelUpEffectIfNeeded(int previousLevel, int currentLevel) {
    if (currentLevel <= previousLevel) return;
    unawaited(AppAudioService.instance.playLevelUp());
  }

  Future<void> _openRouteAndRefresh(String route) async {
    await Navigator.pushNamed(context, route);
    if (mounted) unawaited(_refreshHomeMetrics());
  }

  Future<void> _refreshHomeMetrics() async {
    if (!mounted || _isRefreshingMetrics) return;

    final gameState = context.read<GameStateProvider>();
    if (!gameState.isAuthenticated) return;

    _isRefreshingMetrics = true;
    try {
      await Future.wait([
        gameState.fetchPetStatus(),
        gameState.fetchPetVisual(),
        _refreshDewBalance(gameState),
        _refreshHomeBadges(),
      ]);
    } finally {
      _isRefreshingMetrics = false;
    }
  }

  Future<void> _refreshHomeBadges() async {
    var dailyLoginBadge = _showDailyLoginBadge;
    var missionBadge = _showMissionBadge;
    var notificationBadge = _showNotificationBadge;

    await Future.wait([
      () async {
        final provider = context.read<DailyLoginProvider>();
        await provider.loadDailyLoginStatus();
        final data = provider.calendarData;
        if (data != null) dailyLoginBadge = data.canClaimToday;
      }(),
      () async {
        try {
          final missions = await _missionsRepository.getAllMissions();
          missionBadge = [
            ...missions.dailyMissions,
            ...missions.overallMissions,
          ].any((mission) => mission.canClaim);
        } catch (error) {
          debugPrint(
            'KhÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â´ng thÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â»ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ tÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂºÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â£i badge nhiÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â»ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¡m vÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â»ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¥: $error',
          );
        }
      }(),
      () async {
        try {
          final notifications = await _notificationDatasource.getNotifications(
            1,
            20,
          );
          notificationBadge = notifications.any(
            (notification) => !notification.isRead,
          );
        } catch (error) {
          debugPrint(
            'KhÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â´ng thÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â»ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ tÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚ÂºÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â£i badge thÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â´ng bÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡o: $error',
          );
        }
      }(),
    ]);

    if (!mounted) return;
    setState(() {
      _showDailyLoginBadge = dailyLoginBadge;
      _showMissionBadge = missionBadge;
      _showNotificationBadge = notificationBadge;
    });
  }

  Future<void> _refreshDewBalance(GameStateProvider gameState) async {
    try {
      final wallet = await _walletRepository.getBalance();
      if (!mounted) return;
      setState(() => _dewBalance = wallet.balance);
      final user = gameState.user;
      if (user != null && user.coins != wallet.balance) {
        gameState.setUser(user.copyWith(coins: wallet.balance));
      }
