class _BubbleWidget extends StatefulWidget {
  const _BubbleWidget({
    super.key,
    required this.bubble,
    required this.dewColor,
    required this.petAreaSize,
    required this.petScale,
    required this.petVerticalOffset,
    required this.onCollect,
  });
  final _FloatingBubble bubble;
  final Color dewColor;
  final Size petAreaSize;
  final double petScale;
  final double petVerticalOffset;
  final VoidCallback onCollect;

  @override
  State<_BubbleWidget> createState() => _BubbleWidgetState();
}

class _BubbleWidgetState extends State<_BubbleWidget>
    with SingleTickerProviderStateMixin {
  late final AnimationController _floatCtrl;

  @override
  void initState() {
    super.initState();
    _floatCtrl = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 3000 + widget.bubble.id * 300),
    )..repeat(reverse: true);
  }

  @override
  void dispose() {
    _floatCtrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _floatCtrl,
      builder: (_, __) {
        final yOffset = math.sin(_floatCtrl.value * math.pi) * 12;
        return Positioned(
          top:
              (widget.bubble.top *
                  widget.petAreaSize.height *
                  0.5 *
                  widget.petScale) +
              widget.petVerticalOffset +
              yOffset,
          left: widget.bubble.left * widget.petAreaSize.width,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: widget.onCollect,
            child: Container(
              width: widget.bubble.size,
              height: widget.bubble.size,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color: widget.dewColor.withOpacity(0.25),
                border: Border.all(
                  color: widget.dewColor.withOpacity(0.4),
                  width: 1,
                ),
              ),
              child: Center(
                child: _assetIcon(
                  AppAssets.iconDewDrop,
                  size: widget.bubble.size * 0.5,
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}
